"""PDF122 printed 235–236: significance level, test statistic, acceptance/rejection regions (figure), one- and two-tailed tests (figures), 7.2 procedure (forms of H0/H1)."""
from class12_statistics_common import Builder, save
from class12_statistics_figs import tail_test

RL = {'en': ('Rejection region / Critical value', 'Acceptance region', 'Rejection region / Critical value'),
      'ur': ('ردّ کا علاقہ / فیصلہ کن قیمت', 'قبولیت کا علاقہ', 'ردّ کا علاقہ / فیصلہ کن قیمت'),
      'ps': ('د ردولو سیمه / بحراني قیمت', 'د منلو سیمه', 'د ردولو سیمه / بحراني قیمت')}
CAP = {'right': {'en': 'Right tailed test', 'ur': 'دائیں طرفہ جانچ', 'ps': 'ښي لوري ازموینه'},
       'left': {'en': 'Left tailed test', 'ur': 'بائیں طرفہ جانچ', 'ps': 'کیڼ لوري ازموینه'},
       'two': {'en': 'Two tailed test', 'ur': 'دو طرفہ جانچ', 'ps': 'دوه لوري ازموینه'}}
b = Builder()
b.h('• Significance level', '• معنویت کی سطح', '• د معنی‌داریت کچه')
b.p('The probability of type-I error which we are ready to tolerate in making decision about $H_0$ is called significance level (S.L). It is denoted by α i.e. $\\alpha=P(\\text{reject }H_0/H_0\\text{ is true})$. The higher the significance level we use for testing a hypothesis, the higher the probability of rejecting $H_0$ when it is true. Usually, it is suggested to keep $\\alpha\\le 0.05$.',
    'پہلی قسم کی غلطی کا وہ احتمال جسے ہم $H_0$ کے بارے میں فیصلہ کرتے وقت برداشت کرنے کو تیار ہوں، معنویت کی سطح (S.L) کہلاتا ہے۔ اسے α سے ظاہر کرتے ہیں یعنی $\\alpha=P(\\text{reject }H_0/H_0\\text{ is true})$۔ مفروضے کی جانچ کے لیے ہم جتنی زیادہ معنویت کی سطح استعمال کریں، $H_0$ کے درست ہونے کے باوجود اس کے رد ہونے کا احتمال اتنا ہی زیادہ ہوگا۔ عموماً $\\alpha\\le 0.05$ رکھنے کا مشورہ دیا جاتا ہے۔',
    'د لومړي ډول تېروتنې هغه احتمال چې د $H_0$ په اړه د پرېکړې پر مهال یې زغملو ته چمتو یو، د معنی‌داریت کچه (S.L) بلل کېږي. په α ښودل کېږي یعنې $\\alpha=P(\\text{reject }H_0/H_0\\text{ is true})$. د فرضیې د ازموینې لپاره څومره لوړه د معنی‌داریت کچه وکاروو، هومره د $H_0$ د ردولو احتمال لوړ دی په داسې حال کې چې سمه وي. معمولاً سپارښتنه کېږي چې $\\alpha\\le 0.05$ وساتل شي.')
b.h('• Test statistic and test of significance', '• جانچ کا شماریہ اور معنویت کی جانچ', '• د ازموینې احصاییه او د معنی‌داریت ازموینه')
b.p('A function of sample data is called statistic. When a statistic is used to test a hypothesis, it is called test statistic or decision rule. It helps us in the decision whether to accept or reject $H_0$. The choice of test statistic depends on the hypothesis under question. Commonly used test statistics are Z, t, χ² and F.', 'نمونے کے مواد کے تفاعل کو شماریہ کہتے ہیں۔ جب شماریہ کسی مفروضے کی جانچ کے لیے استعمال ہو تو اسے جانچ کا شماریہ یا فیصلے کا قاعدہ کہتے ہیں۔ یہ ہمیں یہ فیصلہ کرنے میں مدد دیتا ہے کہ $H_0$ کو قبول کریں یا رد۔ جانچ کے شماریے کا انتخاب زیرِ غور مفروضے پر منحصر ہے۔ عام طور پر استعمال ہونے والے جانچ کے شماریے Z، t، χ² اور F ہیں۔', 'د نمونوي معلوماتو تابع ته احصاییه وایي. کله چې احصاییه د یوې فرضیې د ازموینې لپاره وکارول شي، د ازموینې احصاییه یا د پرېکړې قاعده بلل کېږي. دا موږ سره مرسته کوي چې پرېکړه وکړو $H_0$ ومنو که رد یې کړو. د ازموینې د احصاییې ټاکنه د تر پوښتنې لاندې فرضیې پورې اړه لري. عام کارېدونکې د ازموینې احصاییې Z، t، χ² او F دي.')
b.p('The value of test statistic is said to be statistically significant if it falls in the rejection region and as a result $H_0$ is rejected. On the other hand, value of test statistic is said to be statistically insignificant if it falls in the acceptance region and as a result $H_0$ is accepted.', 'جانچ کے شماریے کی قیمت شماریاتی طور پر معنی خیز کہلاتی ہے اگر یہ رد کے علاقے میں آئے اور نتیجتاً $H_0$ رد ہو جائے۔ دوسری طرف جانچ کے شماریے کی قیمت شماریاتی طور پر غیر معنی خیز کہلاتی ہے اگر یہ قبولیت کے علاقے میں آئے اور نتیجتاً $H_0$ قبول ہو جائے۔', 'د ازموینې د احصاییې قیمت احصاییوي معنی‌دار ویل کېږي که د ردولو په سیمه کې ولوېږي او په پایله کې $H_0$ رد شي. له بلې خوا د ازموینې د احصاییې قیمت احصاییوي بې‌معنی ویل کېږي که د منلو په سیمه کې ولوېږي او په پایله کې $H_0$ ومنل شي.')
b.h('• Acceptance and rejection regions', '• قبولیت اور رد کے علاقے', '• د منلو او ردولو سیمې')
b.vpara('stat12-acc-rej-regions', tail_test('two', region_labels=RL['en'], label='Acceptance region between the critical values; rejection regions α/2 in each tail'),
        'All possible values of a test statistic are divided into two mutually exclusive groups. The group of values which lead to the acceptance of $H_0$ is called acceptance region (AR) for the test. The group of values which would lead us to rejection of $H_0$ is called rejection region (RR) or critical region for the test. The values which separate the (AR) and (RR) are called critical values and are obtained from the tables of respective test statistics.',
        'جانچ کے شماریے کی تمام ممکنہ قیمتیں دو باہم مانع گروہوں میں تقسیم کی جاتی ہیں۔ قیمتوں کا وہ گروہ جو $H_0$ کی قبولیت کی طرف لے جائے، جانچ کا قبولیت کا علاقہ (AR) کہلاتا ہے۔ قیمتوں کا وہ گروہ جو ہمیں $H_0$ کے رد کی طرف لے جائے، جانچ کا رد کا علاقہ (RR) یا فیصلہ کن علاقہ کہلاتا ہے۔ (AR) اور (RR) کو الگ کرنے والی قیمتیں فیصلہ کن قیمتیں کہلاتی ہیں اور متعلقہ جانچ کے شماریوں کے جداول سے حاصل کی جاتی ہیں۔',
        'د ازموینې د احصاییې ټول شوني قیمتونه په دوو یو بل منع کوونکو ډلو وېشل کېږي. د قیمتونو هغه ډله چې د $H_0$ منلو ته ورسوي، د ازموینې د منلو سیمه (AR) بلل کېږي. د قیمتونو هغه ډله چې موږ د $H_0$ ردولو ته ورسوي، د ازموینې د ردولو سیمه (RR) یا بحراني سیمه بلل کېږي. هغه قیمتونه چې (AR) او (RR) جلا کوي، بحراني قیمتونه بلل کېږي او د اړوندو احصاییو له جدولونو ترلاسه کېږي.', ratio=.5)
b.h('• One-tailed and two-tailed test', '• یک طرفہ اور دو طرفہ جانچ', '• یو لوري او دوه لوري ازموینه')
b.p('Three types of symbols [>, <, ≠] are used in the alternative hypothesis $H_1$. When the symbols [>, <] are used in $H_1$, it means that the whole rejection region of size α lies only on one tail of the concerned sampling distribution as shown below,', 'متبادل مفروضے $H_1$ میں تین قسم کی علامتیں [>، <، ≠] استعمال ہوتی ہیں۔ جب $H_1$ میں علامتیں [>، <] استعمال ہوں تو اس کا مطلب ہے کہ α سائز کا پورا رد کا علاقہ متعلقہ نمونہ جاتی تقسیم کے صرف ایک کنارے پر ہے جیسا کہ نیچے دکھایا گیا ہے،', 'په بدیله فرضیه $H_1$ کې درې ډوله نښې [>، <، ≠] کارول کېږي. کله چې په $H_1$ کې [>، <] نښې وکارول شي، مانا یې دا ده چې د α اندازې ټوله د ردولو سیمه یوازې د اړوند نمونوي وېش په یوه لکۍ کې پرته ده لکه څنګه چې لاندې ښودل شوي،')
b.visual('stat12-right-tailed', tail_test('right', CAP['right']['en'], label='Right tailed test'), tail_test('right', CAP['right']['ur'], label='Right tailed test'), tail_test('right', CAP['right']['ps'], label='Right tailed test'), ratio=.45)
b.visual('stat12-left-tailed', tail_test('left', CAP['left']['en'], label='Left tailed test'), tail_test('left', CAP['left']['ur'], label='Left tailed test'), tail_test('left', CAP['left']['ps'], label='Left tailed test'), ratio=.45)
b.vpara('stat12-two-tailed', tail_test('two', CAP['two']['en'], label='Two tailed test'),
        'It is called one-sided rejection region and the test is called one-sided or one tailed test. On the other hand when the symbol [≠] is used in $H_1$, it means that the whole rejection region of size α is equally divided; α/2 lies in the right tail and α/2 lies in the left tail of the concerned sampling distribution, as shown in the figure. It is called two sided rejection region and the test is called two-tailed test.',
        'اسے یک طرفہ رد کا علاقہ اور جانچ کو یک طرفہ جانچ کہتے ہیں۔ دوسری طرف جب $H_1$ میں علامت [≠] استعمال ہو تو اس کا مطلب ہے کہ α سائز کا پورا رد کا علاقہ برابر تقسیم ہے؛ α/2 متعلقہ نمونہ جاتی تقسیم کے دائیں کنارے پر اور α/2 بائیں کنارے پر ہے، جیسا کہ شکل میں دکھایا گیا ہے۔ اسے دو طرفہ رد کا علاقہ اور جانچ کو دو طرفہ جانچ کہتے ہیں۔',
        'دې ته یو اړخیزه د ردولو سیمه او ازموینې ته یو لوري ازموینه وایي. له بلې خوا کله چې په $H_1$ کې [≠] نښه وکارول شي، مانا یې دا ده چې د α اندازې ټوله د ردولو سیمه مساوي وېشل شوې؛ α/2 د اړوند نمونوي وېش په ښي لکۍ او α/2 په کیڼ لکۍ کې پرته ده، لکه څنګه چې په شکل کې ښودل شوي. دې ته دوه اړخیزه د ردولو سیمه او ازموینې ته دوه لوري ازموینه وایي.', ratio=.45)
b.h('7.2 General procedure for testing hypothesis about Mean (μ) of a Normal population [when σ² is known]', '7.2 نارمل آبادی کے اوسط (μ) کے بارے میں مفروضے کی جانچ کا عمومی طریقہ [جب σ² معلوم ہو]', '7.2 د نورمال نفوس د منځني (μ) په اړه د فرضیې د ازموینې عمومي طریقه [کله چې σ² معلوم وي]')
b.p('i. Generally $H_0$ and $H_1$ can be set in three different possible forms as follow:', 'i. عام طور پر $H_0$ اور $H_1$ کو تین مختلف ممکنہ شکلوں میں یوں رکھا جا سکتا ہے:', 'i. په عمومي ډول $H_0$ او $H_1$ په درېیو بېلابېلو شونو بڼو داسې ټاکل کېدای شي:')
b.table('stat12-t-h0h1-forms', ['a)', 'b)', 'c)'], [['$H_0:\\mu=\\mu_0$', '$H_0:\\mu\\ge\\mu_0$', '$H_0:\\mu\\le\\mu_0$'], ['$H_1:\\mu\\neq\\mu_0$', '$H_1:\\mu<\\mu_0$', '$H_1:\\mu>\\mu_0$'], ['[Two tailed test]', '[Left tailed test]', '[Right tailed test]']],
        ['a)', 'b)', 'c)'], ['a)', 'b)', 'c)'],
        [['$H_0:\\mu=\\mu_0$', '$H_0:\\mu\\ge\\mu_0$', '$H_0:\\mu\\le\\mu_0$'], ['$H_1:\\mu\\neq\\mu_0$', '$H_1:\\mu<\\mu_0$', '$H_1:\\mu>\\mu_0$'], ['[دو طرفہ جانچ]', '[بائیں طرفہ جانچ]', '[دائیں طرفہ جانچ]']],
        [['$H_0:\\mu=\\mu_0$', '$H_0:\\mu\\ge\\mu_0$', '$H_0:\\mu\\le\\mu_0$'], ['$H_1:\\mu\\neq\\mu_0$', '$H_1:\\mu<\\mu_0$', '$H_1:\\mu>\\mu_0$'], ['[دوه لوري ازموینه]', '[کیڼ لوري ازموینه]', '[ښي لوري ازموینه]']])
rec = b.build('stat12-p122-regions-tails', 'Significance level, test statistic, rejection regions and one/two-tailed tests; 7.2 forms of H₀/H₁', 'معنویت کی سطح، جانچ کا شماریہ، رد کے علاقے اور یک/دو طرفہ جانچ؛ 7.2 H₀/H₁ کی شکلیں', 'د معنی‌داریت کچه، د ازموینې احصاییه، د ردولو سیمې او یو/دوه لوري ازموینې؛ 7.2 د H₀/H₁ بڼې', 122, [235, 236])
for blk in rec['sourceBlocks']:
    if blk['id'] == 'stat12-acc-rej-regions':
        blk['svgUrdu'] = tail_test('two', region_labels=RL['ur'], label='Acceptance and rejection regions')
        blk['svgPashto'] = tail_test('two', region_labels=RL['ps'], label='Acceptance and rejection regions')
    if blk['id'] == 'stat12-two-tailed':
        blk['svgUrdu'] = tail_test('two', CAP['two']['ur'], label='Two tailed test')
        blk['svgPashto'] = tail_test('two', CAP['two']['ps'], label='Two tailed test')

if __name__ == '__main__':
    save(122, [(7, rec)])
